class RemainingLesson(base.Lesson):
 def __init__(self,n):
  self.n=n;self.lesson=DATA['LESSONS'][n-1];self.b=VisualDeck(n,REMAINING_NAMES[n]);base.NAMES[n]=REMAINING_NAMES[n]
  times=[.25,0,0,.5,.75];notes=[]
  for i,t in enumerate(times):
   notes.append({'notes':self.notes(t,['Introduce the title without revealing the explanation.','Read this routine before class; keep teacher pages hidden and use Presenter View.','Prepare the listed materials; resources are teacher-only and must be previewed for fit and spoilers.','Point to today’s position in the full twelve-lesson unit.','Introduce at most three goals and the plain-language vocabulary.'][i],before=PREP[n] if i in [0,2] else '',purpose=self.lesson['slo']['purposeInStoryline'] if i==0 else '',science=(base.resources_audit(n) if i==2 else ''))})
  base.OLD[n]=notes
 def notes(self,minutes,do,key='',say='',check=False,look='',iff='',**kw):
  if check:
   look=look or 'Use the stated task criteria and answer key. Check work across the class, including learners whose first predictions differed.'
   iff=iff or 'Ask: Which observation or diagram feature supports that claim? Give thinking time, then have the learner revise the specific label or reasoning. Follow the source’s targeted support, not a public judgement of the learner.'
  science=kw.pop('science','')+'\n'+SCI[self.n]+'\nSource: V2 Cell Structure Lesson '+str(self.n)+'. Review draft; teacher/source-owner, ARES and native PowerPoint checks remain open.'
  return note(minutes,do,say=say,key=key,look=look,iff=iff,science=science,**kw)
 def add(self,title,phase,mins,*,do,key='',sub='',check=False,say='',**kw):
  return self.b.slide(title,phase,self.notes(mins,do,key=key,say=say,check=check,**kw),sub,check=check)
 def work(self,title,phase,mins,items,*,do,key,sub='',clock=None,check=True,graphic=None,**kw):
  s=self.add(title,phase,mins,do=do,key=key,sub=sub,check=check,**kw)
  steps(s,items,w=7.6 if graphic else 11.8,dy=min(1.13,3.7/max(len(items),1)),size=26 if len(items)<4 else 23,c=COL.get(phase,'47C6E4'))
  if graphic=='notebook':notebook(s,8.7,2.65)
  if graphic=='board':board(s,8.7,2.65,3.6)
  if graphic in ['amina','farm','microscope']:photo(s,graphic,8.5,2.4,3.9)
  if clock:timer(s,clock,x=5.9 if graphic=='board' else 10.65)
  return s
 def q(self,title,phase,mins,prompt,*,do,key,sub='',check=True,clock=None):
  s=self.add(title,phase,mins,do=do,key=key,sub=sub,check=check);question(s,prompt,phase,size=31)
  if clock:timer(s,clock,'think / write')
  return s
 def detail(self,kind,phase,mins,*,do,key,explain=False):
  s=self.add(kind.capitalize()+(' · structure and function' if explain else ' · look for structure'),phase,mins,do=do,key=key,sub='Study the evidence before you explain.' if not explain else 'Connect a feature to the job it enables.',check=explain)
  cell_detail(s,kind,features=not explain)
  if explain:tx(s,FUNCTIONS[kind],6.5,2.9,5.8,2.8,29,INK,True)
  return s
 def summary(self,mins,nextline):
  s=self.add('Summary Table · Lesson '+str(self.n),'Driving Question Board',mins,do='Learners complete their own lesson row, distinguishing observations from explanations. Read two responses if time permits. Unfinished recording can follow teacher policy.',key=SUMMARY[self.n],sub='Record your own evidence and what it helps explain.',reflection=self.lesson['teacherReflection'])
  for i,(head,body) in enumerate([('OBSERVE','What did I see, read or measure?'),('LEARN','What scientific idea helps me explain it?'),('CONNECT','How does this help explain the healing cut?')]):
   xx=.8+i*4.05;badge(s,str(i+1),xx,2.45,list(COL.values())[i]);tx(s,head,xx,3.25,3.7,.4,17,INK,True);tx(s,body,xx,4.0,3.55,1.6,28)
  tx(s,'Next: '+nextline,.85,6.25,11.6,.55,22,INK,True)
 def save(self):
  # Exact phase totals derive from the authored per-screen timings.
  for ph in COL:
   records=[r for r in self.b.records if r['phase']==ph and r['slide']>5 and not r['title'].startswith('Summary Table')]
   if records:
    total=sum(r['minutes'] for r in records);s=self.b.deck.slides[records[0]['slide']-1];tf=s.notes_slide.notes_text_frame
    tf.text=f'{ph.upper()} PHASE ({total:g} minutes total)\n'+tf.text
  self.b.save()


